# ABOUTME: DecodingState classes define what counts as a valid next piece of text
# ABOUTME: for a single "blank" in the JSON template (a choice, a number, or a string).
#
# WHY THIS FILE EXISTS (read this first):
# Our JSON output looks like: {"name": "...", "parameters": {"a": ..., "b": ...}}
# The quotes, braces, and key names are FIXED text we write ourselves.
# Only the "..." parts (the blanks) are actually generated by the LLM, one
# character/token at a time. Each class below is the "rulebook" for ONE kind
# of blank: it answers two simple questions, over and over, as text is typed:
#   1) is_valid_addition(next_piece) -> can I add this without breaking the rule?
#   2) can_stop()                    -> is what I have right now already a
#                                        complete, valid value?

from abc import ABC, abstractmethod


class DecodingState(ABC):
    """Base class: one "blank" being filled in, one token at a time.

    Think of this as a tiny state machine. `generated_text` is "what has
    been typed into this blank so far". Every subclass below just defines
    different rules for what's allowed.
    """

    def __init__(self) -> None:
        self.generated_text: str = ""  # nothing typed into this blank yet

    @abstractmethod
    def is_valid_addition(self, addition: str) -> bool:
        """Would adding `addition` still respect this blank's rule?"""

    @abstractmethod
    def can_stop(self) -> bool:
        """Is `generated_text` already a complete, acceptable value?"""

    def accept(self, addition: str) -> None:
        """Called once we've DECIDED to add `addition` (it already passed
        is_valid_addition). This just grows the text we've typed so far.
        """
        self.generated_text += addition


class ChoiceState(DecodingState):
    """Rule: the blank must become exactly one string from a fixed list.

    Used for two things in this project:
      - the function name (choices = every known function name)
      - a boolean value (choices = ["true", "false"])

    The trick: while typing, we only know a PREFIX so far (e.g. "fn_ad").
    We allow it as long as it's still the start of at least one choice.
    """

    def __init__(self, choices: list[str]) -> None:
        super().__init__()
        if not choices:
            raise ValueError("ChoiceState requires at least one choice")
        self._choices = choices

    def is_valid_addition(self, addition: str) -> bool:
        # "what we'd have typed if we accepted this addition"
        candidate = self.generated_text + addition
        # Allowed if at least one full choice still starts with it.
        # Example: choices=["fn_add_numbers"], candidate="fn_ad"
        #          -> "fn_add_numbers".startswith("fn_ad") is True -> OK
        return any(choice.startswith(candidate) for choice in self._choices)

    def can_stop(self) -> bool:
        # We can only stop if we've typed one of the choices EXACTLY,
        # not just a prefix of one.
        return self.generated_text in self._choices


class NumberState(DecodingState):
    """Rule: the blank must be a valid JSON "number" (float-style).

    Valid shape: an optional leading "-", then digits, then at most one
    "." followed by more digits. Examples that are fine mid-generation:
    "", "-", "4", "4.", "4.5"   (note: "4." alone is NOT a finished number
    yet — can_stop() must say False until at least one digit follows the dot
    too... actually here we just require it not to END on a bare dot).
    """

    def is_valid_addition(self, addition: str) -> bool:
        return self._is_number_prefix(self.generated_text + addition)

    def can_stop(self) -> bool:
        return self._is_complete_number(self.generated_text)

    @staticmethod
    def _is_number_prefix(text: str) -> bool:
        """Could `text` still become a valid number if we keep typing?"""
        if text in ("", "-"):
            return True  # nothing yet, or just a minus sign: still OK so far
        seen_dot = False
        for index, char in enumerate(text):
            if char == "-":
                if index != 0:
                    return False  # a "-" is only allowed as the very first char
            elif char == ".":
                if seen_dot:
                    return False  # a second "." is never valid in a number
                seen_dot = True
            elif not char.isdigit():
                return False  # anything else (letters, etc.) is invalid
        return True

    @staticmethod
    def _is_complete_number(text: str) -> bool:
        """Is `text`, as it stands right now, already a FINISHED number?"""
        if text in ("", "-") or text.endswith("."):
            return False  # "", "-", "4." are not finished numbers
        try:
            float(text)  # reuse Python's own parser as the final sanity check
        except ValueError:
            return False
        return True


class IntegerState(DecodingState):
    """Same idea as NumberState, but NO decimal point is ever allowed.

    Needed because the schema distinguishes "number" (-> Python float) from
    "integer" (-> Python int). Example: n=4 must stay the integer 4, not 4.0.
    """

    def is_valid_addition(self, addition: str) -> bool:
        return self._is_integer_prefix(self.generated_text + addition)

    def can_stop(self) -> bool:
        # Anything except "" or a lone "-" is a complete integer.
        text = self.generated_text
        return text not in ("", "-")

    @staticmethod
    def _is_integer_prefix(text: str) -> bool:
        if text in ("", "-"):
            return True
        body = text[1:] if text[0] == "-" else text  # strip an optional leading "-"
        return body.isdigit()  # everything left must be plain digits


class StringState(DecodingState):
    """Rule: the blank must be the CONTENT of a JSON string (no surrounding
    quotes here — those are fixed template text added by the caller).

    The tricky part: some real values need to CONTAIN a '"' or a '\\'
    character (example: a Windows path "C:\\Users\\john", or a regex "\\d+").
    If we just banned those characters outright, those values would be
    impossible to generate correctly. So instead we follow the SAME escaping
    rule real JSON uses:
        \\"  means: "a literal quote character goes here"
        \\\\ means: "a literal backslash character goes here"
    A backslash that is NOT immediately followed by one of those is not
    allowed (we only support these two escapes, which covers every real
    case in this project).

    `generated_text` stores the RAW typed characters (still containing the
    backslash escapes). Call `unescape()` at the end to get the real value.
    """

    def is_valid_addition(self, addition: str) -> bool:
        # We check one character at a time so this also works correctly
        # even if a single token's text is several characters long.
        text = self.generated_text
        for char in addition:
            if self._pending_escape(text):
                # The previous character was an "open" backslash, so THIS
                # character must complete a known escape: \" or \\.
                if char not in ('"', "\\"):
                    return False
            elif char == '"':
                # A quote that is NOT escaped means "end of string" — not
                # allowed as part of the content itself.
                return False
            text += char  # keep "simulating" so the next char is checked right
        return True

    def can_stop(self) -> bool:
        # We can never stop in the middle of an escape sequence (right
        # after a lone backslash) — we'd produce broken JSON.
        return not self._pending_escape(self.generated_text)

    @staticmethod
    def _pending_escape(text: str) -> bool:
        """True if `text` currently ends with an "open" backslash.

        We count trailing backslashes: an ODD count means the last one is
        still waiting to be paired with \\" or \\\\ (e.g. "ab\\" -> 1
        trailing backslash -> pending). An EVEN count (0, 2, 4...) means
        every backslash so far is already paired up -> not pending.
        """
        count = 0
        for char in reversed(text):
            if char != "\\":
                break
            count += 1
        return count % 2 == 1

    def unescape(self) -> str:
        """Turn the raw typed text (with \\" and \\\\) into the real value.

        Example: raw 'Say \\"hi\\"' (contains the 2-character sequence \\"
        twice) becomes the real string: Say "hi"
        """
        result: list[str] = []
        text = self.generated_text
        i = 0
        while i < len(text):
            if text[i] == "\\" and i + 1 < len(text) and text[i + 1] in ('"', "\\"):
                result.append(text[i + 1])  # keep only the escaped character
                i += 2  # skip both the backslash and the escaped character
            else:
                result.append(text[i])
                i += 1
        return "".join(result)